import{_ as s,o as e,c as n,a2 as l}from"./chunks/framework.C2TvIV46.js";const d=JSON.parse('{"title":"Example scripts","description":"","frontmatter":{},"headers":[],"relativePath":"language/examples.md","filePath":"language/examples.md"}'),t={name:"language/examples.md"};function p(o,a,c,r,i,g){return e(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="example-scripts" tabindex="-1">Example scripts <a class="header-anchor" href="#example-scripts" aria-label="Permalink to &quot;Example scripts&quot;">​</a></h1><p>The HREK ships a <code>simple/</code> folder of minimal, teaching-commented Megalo scripts. This page walks through three of them, explaining each line and linking back to the relevant language concepts.</p><p>Source location in a default HREK install:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/multiplayer/megalo/simple/</span></span></code></pre></div><h2 id="_1-slayer-—-one-point-per-kill" tabindex="-1">1. Slayer — one point per kill <a class="header-anchor" href="#_1-slayer-—-one-point-per-kill" aria-label="Permalink to &quot;1. Slayer — one point per kill&quot;">​</a></h2><p>The simplest possible scoring script. From <code>simple/slayer/1.txt</code>:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">;this script gives one point for killing an enemy player</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">;loop over all players</span></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">;did this player die from an enemy this tick?</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">player_died</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-enumMember">enemy</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">;create a temporary variable to store the killer in</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">player</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">;this gets the player who killed current_player and stores it in killer</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">player_death_get_killing_player</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">;increase killer&#39;s score by 1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">;score is a built-in numeric player member variable</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">killer</span><span class="megalo-operator">.</span><span class="megalo-property">score</span><span class="megalo-text"> </span><span class="megalo-keyword">add</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h3 id="walkthrough" tabindex="-1">Walkthrough <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;Walkthrough&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Line</th><th>Explanation</th></tr></thead><tbody><tr><td><code>trigger player</code></td><td>A <a href="/MegaloEvolved/beta/docs/language/elements/trigger#trigger-kinds">player trigger</a> — runs once per player, per tick. <code>current_player</code> is set to each player in turn.</td></tr><tr><td><code>condition player_died current_player enemy</code></td><td>A <a href="/MegaloEvolved/beta/docs/language/elements/trigger/condition">condition</a> that checks whether <code>current_player</code> was killed by an enemy this tick. If false, the trigger halts.</td></tr><tr><td><code>temporary player killer none</code></td><td>Declares a <a href="/MegaloEvolved/beta/docs/language/variable-model#temporary-variables">temporary variable</a> of type <code>player</code>, initialized to <code>none</code>.</td></tr><tr><td><code>action player_death_get_killing_player current_player killer</code></td><td>A <a href="/MegaloEvolved/beta/docs/language/elements/trigger/action#getter-actions">getter action</a> — writes the killing player into <code>killer</code>.</td></tr><tr><td><code>action set killer.score add 1</code></td><td>The <a href="/MegaloEvolved/beta/docs/language/elements/trigger/action#the-set-action">set action</a> — adds 1 to the killer&#39;s built-in <code>.score</code> member variable.</td></tr></tbody></table><p>This script has no <code>variables</code> block, no <code>engine_data</code>, and no includes. It relies entirely on built-in member variables and context references.</p><h2 id="_2-koth-—-scoring-time-in-hills" tabindex="-1">2. KOTH — scoring time in hills <a class="header-anchor" href="#_2-koth-—-scoring-time-in-hills" aria-label="Permalink to &quot;2. KOTH — scoring time in hills&quot;">​</a></h2><p>A slightly richer script that uses object triggers, timers, and nested <code>for_each</code>. From <code>simple/koth/1.txt</code>:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">; simple version of KOTH - every hill object placed on the map can be scored in</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">timer</span><span class="megalo-text"> </span><span class="megalo-variable">time_in_hill</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">;pause all players&#39; timers</span></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">timer_set_rate</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-property">time_in_hill</span><span class="megalo-text"> </span><span class="megalo-number">0</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">;find all the hill objects</span></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">object</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">object_is_type</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-enumMember">&quot;area&quot;</span></span>
<span class="line"><span class="megalo-text">	</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">; set up navpoint icon and boundary for the hill object</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">navpoint_set_visible</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-enumMember">everyone</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">navpoint_set_icon</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-enumMember">king</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">navpoint_set_priority</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-enumMember">normal</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">boundary_set_visible</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-text">	</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-comment">;unpause timers for players in the hill</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action for_each </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-comment">;note you can use a player reference as an object reference</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-comment">;note that we are using the current_object variable from the outer trigger</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">condition </span><span class="megalo-function">object_in_area</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action </span><span class="megalo-function">timer_set_rate</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-property">time_in_hill</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">		</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-comment">;if a guy is in here, let&#39;s make the icon blink</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action </span><span class="megalo-function">navpoint_set_priority</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-text"> </span><span class="megalo-enumMember">blink</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">;when players&#39; timers expire, they have spent 1 second in the hill</span></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">player</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">timer_expired</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-property">time_in_hill</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">timer_reset</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-property">time_in_hill</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">current_player</span><span class="megalo-operator">.</span><span class="megalo-property">score</span><span class="megalo-text"> </span><span class="megalo-keyword">add</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h3 id="walkthrough-1" tabindex="-1">Walkthrough <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;Walkthrough&quot;">​</a></h3><p><strong>Variables block:</strong></p><table tabindex="0"><thead><tr><th>Line</th><th>Explanation</th></tr></thead><tbody><tr><td><code>variables player</code></td><td>Declares <a href="/MegaloEvolved/beta/docs/language/variable-model#scopes">player-scoped variables</a> — each player gets their own copy.</td></tr><tr><td><code>networked timer time_in_hill 1</code></td><td>A <a href="/MegaloEvolved/beta/docs/language/variable-model#network-state">networked timer</a> initialized to 1 second.</td></tr></tbody></table><p><strong>Trigger 1 — pause timers:</strong></p><table tabindex="0"><thead><tr><th>Line</th><th>Explanation</th></tr></thead><tbody><tr><td><code>trigger player</code></td><td>Runs for every player, every tick.</td></tr><tr><td><code>action timer_set_rate current_player.time_in_hill 0</code></td><td><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action#timer-actions">Pauses</a> each player&#39;s hill timer. Rate <code>0</code> means stopped.</td></tr></tbody></table><p><strong>Trigger 2 — hill objects:</strong></p><table tabindex="0"><thead><tr><th>Line</th><th>Explanation</th></tr></thead><tbody><tr><td><code>trigger object</code></td><td>An <a href="/MegaloEvolved/beta/docs/language/elements/trigger#trigger-kinds">object trigger</a> — runs for every object, with <code>current_object</code> set.</td></tr><tr><td><code>condition object_is_type current_object &quot;area&quot;</code></td><td>Only continues for KOTH hill objects (type <code>&quot;area&quot;</code> from <a href="/MegaloEvolved/beta/docs/language/object-lists">object lists</a>).</td></tr><tr><td>Navpoint actions</td><td>Sets up the hill&#39;s <a href="/MegaloEvolved/beta/docs/language/elements/trigger/action#navpoint-actions">navpoint and boundary</a> for all players.</td></tr><tr><td><code>action for_each player</code></td><td>A <a href="/MegaloEvolved/beta/docs/language/elements/trigger#for_each-sub-triggers">nested sub-trigger</a> iterating over all players.</td></tr><tr><td><code>condition object_in_area current_player current_object</code></td><td>Checks if the player is inside this hill. Uses a <a href="/MegaloEvolved/beta/docs/language/references#player-as-object-references">player-as-object reference</a>.</td></tr><tr><td><code>action timer_set_rate current_player.time_in_hill 1</code></td><td>Unpauses the timer for players inside the hill.</td></tr><tr><td><code>action navpoint_set_priority current_object blink</code></td><td>Makes the hill icon blink when occupied.</td></tr></tbody></table><p><strong>Trigger 3 — award points:</strong></p><table tabindex="0"><thead><tr><th>Line</th><th>Explanation</th></tr></thead><tbody><tr><td><code>condition timer_expired current_player.time_in_hill</code></td><td>Fires when a player&#39;s hill timer reaches zero (1 second elapsed).</td></tr><tr><td><code>action timer_reset current_player.time_in_hill</code></td><td>Restarts the timer for the next second.</td></tr><tr><td><code>action set current_player.score add 1</code></td><td>Awards one point.</td></tr></tbody></table><h3 id="how-the-three-triggers-work-together" tabindex="-1">How the three triggers work together <a class="header-anchor" href="#how-the-three-triggers-work-together" aria-label="Permalink to &quot;How the three triggers work together&quot;">​</a></h3><p>Every tick:</p><ol><li>Trigger 1 pauses all hill timers.</li><li>Trigger 2 finds hill objects, and for each hill, unpauses timers for players inside it.</li><li>Trigger 3 awards a point whenever a player&#39;s timer expires (meaning they were in a hill for 1 full second).</li></ol><p>The pause-unpause pattern ensures timers only count down while a player is physically inside a hill.</p><h2 id="_3-ctf-—-multi-flag-capture-the-flag" tabindex="-1">3. CTF — multi-flag capture the flag <a class="header-anchor" href="#_3-ctf-—-multi-flag-capture-the-flag" aria-label="Permalink to &quot;3. CTF — multi-flag capture the flag&quot;">​</a></h2><p>A more complete gametype script with map objects, team variables, and multiple cooperating triggers. From <code>simple/ctf/1.txt</code>:</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">;simple version of multi-flag CTF</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">game_options</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">teams_enabled</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">3</span></span>
<span class="line"><span class="megalo-text">		</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">player_traits</span><span class="megalo-text"> </span><span class="megalo-variable">flag_carrier_traits</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-string">&quot;Flag Carrier Traits&quot;</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-string">&quot;Traits applied to players carrying flags&quot;</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-parameter">speed</span><span class="megalo-text"> </span><span class="megalo-number">75</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">map_object</span><span class="megalo-text"> </span><span class="megalo-variable">flag_spawn_point</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">label</span><span class="megalo-text"> </span><span class="megalo-string">&quot;ctf_flag_spawn&quot;</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">team</span><span class="megalo-text"> each</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">map_object</span><span class="megalo-text"> </span><span class="megalo-variable">flag_return_point</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">label</span><span class="megalo-text"> </span><span class="megalo-string">&quot;ctf_flag_return&quot;</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">team</span><span class="megalo-text"> each</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">variables</span><span class="megalo-text"> </span><span class="megalo-type">team</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">object</span><span class="megalo-text"> </span><span class="megalo-variable">flag_spawn</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">networked</span><span class="megalo-text"> </span><span class="megalo-type">object</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-text"> </span><span class="megalo-variable">none</span><span class="megalo-text">	</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>The trigger element (abbreviated):</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-comment">;set up flag spawns (only use one, even if more than one are on the map)</span></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">team</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag_spawn </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action for_each </span><span class="megalo-text">flag_spawn_point</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-operator">.</span><span class="megalo-property">team</span><span class="megalo-text"> </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag_spawn </span><span class="megalo-keyword">set_to</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">;spawn flags</span></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">team</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">team_is_active</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">condition not </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag_spawn </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">	</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">create_object</span><span class="megalo-text"> </span><span class="megalo-enumMember">&quot;flag&quot;</span><span class="megalo-text"> </span><span class="megalo-parameter">at</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag_spawn </span><span class="megalo-parameter">set</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag </span><span class="megalo-enumMember">never_garbage</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">temporary </span><span class="megalo-type">object</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-variable">flag</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-operator">.</span><span class="megalo-property">team</span><span class="megalo-text"> </span><span class="megalo-keyword">set_to</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span></span>
<span class="line"><span class="megalo-text">	</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">navpoint_set_icon</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-text"> </span><span class="megalo-enumMember">flag</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action </span><span class="megalo-function">navpoint_set_visible</span><span class="megalo-text"> </span><span class="megalo-variable">flag</span><span class="megalo-text"> </span><span class="megalo-enumMember">everyone</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-comment">; did we score?</span></span>
<span class="line"><span class="megalo-keyword">trigger</span><span class="megalo-text"> </span><span class="megalo-type">team</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">action for_each </span><span class="megalo-text">flag_return_point</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">condition not </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> </span><span class="megalo-variable">none</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">condition </span><span class="megalo-function">if</span><span class="megalo-text"> </span><span class="megalo-variable">current_object</span><span class="megalo-operator">.</span><span class="megalo-property">team</span><span class="megalo-text"> </span><span class="megalo-keyword">equal_to</span><span class="megalo-text"> carrier</span><span class="megalo-operator">.</span><span class="megalo-property">team</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">condition </span><span class="megalo-function">object_in_area</span><span class="megalo-text"> carrier </span><span class="megalo-variable">current_object</span></span>
<span class="line"><span class="megalo-text">	</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action </span><span class="megalo-function">delete_object</span><span class="megalo-text"> </span><span class="megalo-variable">current_team</span><span class="megalo-operator">.</span><span class="megalo-text">flag</span></span>
<span class="line"><span class="megalo-text">		</span><span class="megalo-keyword">action </span><span class="megalo-function">set</span><span class="megalo-text"> carrier</span><span class="megalo-operator">.</span><span class="megalo-property">score</span><span class="megalo-text"> </span><span class="megalo-keyword">add</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">end</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h3 id="key-concepts-demonstrated" tabindex="-1">Key concepts demonstrated <a class="header-anchor" href="#key-concepts-demonstrated" aria-label="Permalink to &quot;Key concepts demonstrated&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Concept</th><th>Where</th></tr></thead><tbody><tr><td><a href="/MegaloEvolved/beta/docs/language/elements/game-options">game_options overrides</a></td><td><code>override teams_enabled true</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/elements/game-options/player-traits">player_traits</a></td><td><code>flag_carrier_traits</code> with <code>speed 75</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/elements/map-object">map_object labels</a></td><td><code>flag_spawn_point</code>, <code>flag_return_point</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/variable-model#scopes">team-scoped variables</a></td><td><code>flag_spawn</code>, <code>flag</code> on <code>variables team</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/elements/trigger#trigger-kinds">team triggers</a></td><td>All four triggers use <code>trigger team</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/elements/trigger#for_each-sub-triggers">for_each with map object filter</a></td><td><code>for_each flag_spawn_point</code></td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action#object-actions">create_object</a></td><td>Spawns a flag at the team&#39;s spawn</td></tr><tr><td><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action#getter-actions">Getter + scoring pattern</a></td><td><code>get_player_holding_object</code> then score on capture</td></tr></tbody></table><h2 id="more-examples" tabindex="-1">More examples <a class="header-anchor" href="#more-examples" aria-label="Permalink to &quot;More examples&quot;">​</a></h2><p>The <code>simple/</code> folder contains additional scripts for other gametypes:</p><table tabindex="0"><thead><tr><th>Folder</th><th>Scripts</th><th>Concepts</th></tr></thead><tbody><tr><td><code>simple/slayer/</code></td><td>1.txt, 2.txt</td><td>Basic and team scoring</td></tr><tr><td><code>simple/koth/</code></td><td>1.txt – 6.txt</td><td>Hill timers, territories, crazy king</td></tr><tr><td><code>simple/ctf/</code></td><td>1.txt – 4.txt</td><td>Flag spawn, capture, return, neutral flag</td></tr><tr><td><code>simple/juggernaut/</code></td><td>1.txt</td><td>Juggernaut assignment and traits</td></tr></tbody></table><p>For full-scale production scripts, see the main HREK <code>megalo/</code> folder (e.g. <code>slayer_gameplay_triggers.txt</code>, <code>3nvasion.txt</code>).</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/language/">Introduction</a> — language overview</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger">trigger</a> — trigger kinds and execution</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/condition">condition</a> — condition syntax</li><li><a href="/MegaloEvolved/beta/docs/language/elements/trigger/action">action</a> — action syntax</li><li><a href="/MegaloEvolved/beta/docs/language/variable-model">Variable model</a> — variable declarations</li></ul>`,39)])])}const h=s(t,[["render",p]]);export{d as __pageData,h as default};
